    @Test
    public void testParseHandlerType_withNullHandlerTypeName() {
        HANDLER_TYPE result = BasicContentHandlerFactory.parseHandlerType(null, HANDLER_TYPE.MARKDOWN);
        assertEquals(HANDLER_TYPE.MARKDOWN, result);
    }

    @Test
    public void testParseHandlerType_withValidHandlerTypeName() {
        HANDLER_TYPE result = BasicContentHandlerFactory.parseHandlerType("xml", HANDLER_TYPE.MARKDOWN);
        assertEquals(HANDLER_TYPE.XML, result);
    }

    @Test
    public void testParseHandlerType_withInvalidHandlerTypeName() {
        HANDLER_TYPE result = BasicContentHandlerFactory.parseHandlerType("unknown", HANDLER_TYPE.MARKDOWN);
        assertEquals(HANDLER_TYPE.MARKDOWN, result);
    }

    @Test
    public void testParseHandlerType_withDefaultType() {
        HANDLER_TYPE result = BasicContentHandlerFactory.parseHandlerType("unknown", null);
        assertEquals(HANDLER_TYPE.MARKDOWN, result);
    }

    @Test
    public void testParseHandlerType_withEmptyString() {
        HANDLER_TYPE result = BasicContentHandlerFactory.parseHandlerType("", HANDLER_TYPE.MARKDOWN);
        assertEquals(HANDLER_TYPE.MARKDOWN, result);
    }

    @Test
    public void testParseHandlerType_withWhitespace() {
